BUNDLE = {"19-creator-komplettpaket": ["01", "02", "03", "04", "05", "07", "09", "16", "17"], "20-content-paket": ["10", "11", "12", "13", "14", "15"], "27-abo-creator-komplettpaket": ["21", "22", "23", "24", "25", "26"]}
BOARD = {}
for s in C:
    n = s[:2]
    BOARD[s] = ("Abo Creator Vorlagen" if n in ("21", "22", "23", "24", "25", "26", "27") else
                "Media Kit Vorlagen" if n in ("01", "02", "07", "09", "19") else
                "Instagram Vorlagen" if n in ("08", "13", "14", "15") else
                "Content Planung und Hooks" if n in ("10", "11", "12", "20") else "Creator Business Vorlagen")
DESC = ["{sub}. Die {kw} spart dir Zeit und sieht professionell aus. Auf Deutsch, Sofort-Download.",
        "Mit dieser {kw} trittst du auf wie ein Profi: {sub}. Bearbeitbar in Canva und PowerPoint.","{sub}. {kw} auf Deutsch, für Canva und PowerPoint, sofort zum Download.",
        "Du suchst eine {kwl}? {sub}. Komplett auf Deutsch und in Minuten angepasst.",
        "{kw}: {sub}. Einfach in Canva öffnen, eigene Texte und Fotos rein, fertig.",
        "Spar dir Stunden in Canva: {sub}. Vorlage auf Deutsch zum Sofort-Download."]
LAYOUTS = ["faecher", "geraet", "zoom", "foto", "liste", "frage"]
BGS = ["hell", "dunkel", "farbe"]
ideas = []
for s, (kw, heads, subs, bullets, tags) in C.items():
    lays = ["faecher", "geraet", "zoom", "frage"] if s in BUNDLE else LAYOUTS
    combos = [(L, h) for h in range(4) for L in lays][: (8 if s in BUNDLE else 12)]
    # spread so the same headline is not paired with the same layout twice
    combos = [(lays[(i + i // len(lays)) % len(lays)], i % 4) for i in range(len(combos))]
    for i, (L, h) in enumerate(combos):
        sub = subs[(h + i) % 4]
        pre = ["", "Neu: ", "Tipp: ", "Für Creator: "][(i // 4) % 4]
        title = f"{pre}{kw} – {sub}"[:100]
        hs = " ".join("#" + t for t in (tags[i % 4:] + tags[:i % 4]))
        ideas.append({"id": f"{s[:2]}-{i + 1:02d}", "slug": s, "layout": L, "bg": BGS[(i + h) % 3], "headline": heads[h], "sub": sub,
                      "bullets": bullets, "bundle": BUNDLE.get(s, []), "title": title,
                      "desc": DESC[i % 6].format(sub=sub, kw=kw, kwl=kw[0].lower() + kw[1:]) + " " + hs, "board": BOARD[s], "status": "neu"})
os.makedirs(OUT, exist_ok=True)
json.dump(ideas, open(os.path.join(OUT, "ideen.json"), "w"), ensure_ascii=False, indent=1)
print(len(ideas), "Ideen")
